    public static class LeonardodaVinci
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Gli animali sono esemplo de la vita mondiale.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "I' ho tanti vocabuli nella mia lingua materna, ch'io m'ho più tosto da doler del bene intendere le cose, che del mancamento delle parole colle quali io possa bene esprimere il concetto della mente mia.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il resto della difinizione dell'anima lascio nelle mente de' frati, padri de' popoli, li quali per ispiratat'azione san tutti li segreti. Lascia star le lettere incoronate perché son somma verità.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "L'omo e li animali sono propio transito e condotto di cibo, sepoltura di animali, albergo de' morti, facendo a sé vita dell'altrui morte, guaina di corruzione.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "L'uffizio del muscolo è di tirare e non di spingere, eccetto li membri genitali e la lingua.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La passione dell'animo caccia via la lussuria.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Salvatico è quel che si salva.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Se bene, come loro, non sapessi allegare gli altori, molto maggiore e più degna cosa allegherò, allegando la sperienzia, maestra ai loro maestri.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "A torto si lamentano li omini della innocente esperienzia, quella accusando di fallacie e di bugiarde dimonstrazioni.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Acquista cosa nella tua gioventù che ristori il danno della tua vecchiezza.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi altri offende, sé non sicura.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi biasima la somma certezza delle matematiche si pasce di confusione, e mai porrà silenzio alle contradizioni delle sofistiche scienzie, colle quali s'impara uno eterno gridore.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi disputa allegando l'autorità, non adopra lo 'ngegno, ma più tosto la memoria.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi non punisce il male, comanda che si facci.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi non raffrena la volontà colle bestie s'accompagni.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi non stima la vita, non la merita.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi poco pensa molto erra.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi tempo ha e tempo aspetta, perde l'amico e danari non ha mai.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Chi vol essere ricco in un dì è impiccato in un anno.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Come è più difficile a 'ntendere l'opere di natura che un libro d'un poeta.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Costanzia: non chi comincia, ma quel che persevera.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Dimanda consiglio a chi ben si corregge.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Iddio ci vende tutti li beni per prezzo di fatica.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il moto è causa d'ogni vita.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Gola è mantenimento della vita.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "L'acqua che tocchi de' fiumi è l'ultima di quella che andò e la prima di quella che viene. Così il tempo presente.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "L'anima desidera stare col suo corpo, perché, sanza li strumenti organici di tal corpo, nulla può oprare né sentire.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "L'età che vola discorre nascostamente e inganna altrui, e niuna cosa è più veloce che gli anni, e chi semina virtù fama raccoglie.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "L'uomo ha grande discorso del quale la più parte è vano e falso, li animali l'hanno piccolo ma è utile e vero; e meglio è la piccola certezza che la gran bugia.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La natura è piena d'infinite ragioni, che non furon mai in isperienzia.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La paura nasce più tosto che altra cosa.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La sapienza è figliola della sperienzia.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La scienza è il capitano, e la pratica sono i soldati.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La somma felicità sarà somma cagione della infelicità, e la perfezion della sapienza cagion della stoltizia.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La verità sola fu figliola del tempo.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La vita bene spesa lunga è.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Lussuria è causa della generazione.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Nessuna azione naturale si po' abreviare.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Nessuno effetto è in natura sanza ragione; intendi la ragione e non ti bisogna sperienza.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "No' si volta chi a stella è fisso.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Non si dimanda ricchezza quella che si può perdere. La virtù è vero nostro bene ed è vero premio del suo possessore: lei non si può perdere, lei non ci abbandona, se prima la vita non ci lascia.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Non si po' aver ragione né minor signoria che quella di se medesimo.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "O studianti, studiate le matematiche, e non edificate sanza fondamenti.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Ogni danno lascia dispiacere nella ricordazione, salvo che 'l sommo danno, cioè la morte che uccide essa ricordazione insieme colla vita.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Ogni nostra cognizione prencipia da sentimenti.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Più facilmente si contasta al principio che alla fine.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Quelli che s'innamoran di pratica sanza scienzia son come 'l nocchier ch'entra in navilio senza timone o bussola, che mai ha certezza dove si vada.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo per isperienza è provato, che chi non si fida mai sarà ingannato.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Raro cade chi ben cammina.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Reprendi l'amico tuo in segreto e laldalo in paleso.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Sì come una giornata bene spesa dà lieto dormire, così una vita bene usata dà lieto morire.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Tristo è quel discepolo che non avanza il suo maestro.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Una volta che abbiate conosciuto il volo, camminerete sulla terra guardando il cielo, perché là siete stati e là desidererete tornare.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Un vaso rotto crudo si può riformare, ma il cotto no.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Del nibbio si legge che, quando esso vede i suoi figlioli nel nido esser di troppa grassezza, che egli gli becca loro le coste, e tiengli sanza mangiare.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il rospo si pasce di terra, e sempre sta macro, perché non si sazia: tanto è il timore, che essa terra non li manchi.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La sirena sì dolcemente canta, che addormenta i marinari, e essa monta sopra i navili, e occide li addormentati marinari.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Benché le pernici rubino l'ova l'una all'altra, non di meno i figlioli, nati d'esse ova, sempre ritornano alla lor vera madre.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La volpe, quando vede alcuna torma di sgazze o taccole o simili uccelli, subito si gitta in terra in modo, colla bocca aperta, che par morta; e essi occelli le voglian beccare la lingua, e essa gli piglia la testa.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La talpa ha li occhi molto piccoli e sempre sta sotto terra, e tanto vive quanto essa sta occulta, e, come viene alla luce, subito more perché si fa nota. Così la bugia.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La lepre sempre teme, e le foglie, che caggiano dalle piante per autunno, sempre la tengano in timore e, 'l più delle volte, in fuga.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il falcone non preda mai, se non l'uccelli grossi, e prima si lascerebbe morire, che si cibassi de' piccioli, e che mangiasse carne fetida.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "In questo vizio, si legge del pagone esserli più che altro animale sottoposto, perché sempre contempla in nella bellezza della sua coda, quella allargando in forma di rota, e col suo grido trae a sé la vista de' circustanti animali.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Alla costanza s'assimiglia la fenice; la quale, intendendo per natura la sua rennovazione, è costante a sostenere le cocenti fiamme, le quali la consumano, e poi di novo rinasce.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il rondone si mette per la inconstanza: il quale sempre sta in moto, per non sopportare alcuno minimo disagio.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il salvatico asino quando va alla fonte per bere e truova l'acqua intorbidata, non arà mai sì gran sete che non s'astenga di bere e aspetti ch'essa acqua si rischiari.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "L'avvoltoio è tanto sottoposto alla gola che andrebbe mille miglia per mangiare d'una carogna e per questo seguita li eserciti.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La tortora non fa mai fallo al suo compagno, e, se l'uno more, l'altro osserva perpetua castità, e non si posa mai su ramo verde, e non bee mai acqua chiara.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "L'ermellino, per la sua moderanza, non mangia se non una sola volta al dì, e prima si lascia pigliare a' cacciatori che voler fuggire nella infangata tana — per non maculare la sua gentilezza.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo porta grande amore a' sua nati, e, trovando quelli nel nido morti dal serpente, si punge a riscontro al core, e, col suo piovente sangue bagnandoli, li torna in vita.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La salamandra nel foco raffina la sua scorza. Per la virtù: questa non ha membra passive, e non si prende la cura d'altro cibo che di foco, e spesso in quello rinnova la sua scorza.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo converte il ferro in suo nutrimento; cova l'ova colla vista.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Cigno è candido, sanza alcuna macchia e dolcemente canta nel morire; il qual canto termina la vita.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questa, bevendo la salsa acqua, caccia da sé il male; se truova la compagna in fallo, l'abbandona, e, quando è vecchia, i sua figlioli la covano e pascano, in fin che more.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questa col suo canto fa tacere il cucco; more nell'olio e rinasce nell'aceto; canta per li ardenti caldi.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo porta ne' denti la subita morte, e, per non sentire l'incanti, colla coda si stóppa li orecchi.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Quest'ha nel suo, ch'apre bocca, e nel fine strigne' denti, e ammazza il marito; poi i figlioli, in corpo cresciuti, straccian il ventre, e occidano la madre.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il ragno partorisce fori di sé l'artificiosa e maestrevole tela, la quale gli rende, per benefizio, la presa preda.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo animale col suo tonante grido desta i sua figlioli, dopo il terzo giorno nati, aprendo a quelli tutti l'indormentati sensi: e tutte le fiere, che nella selva sono, fuggano.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Queste castigano i loro schermidori, privandoli di vita, ché così ha ordinato natura, perché si cibino.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo dov'è più luce, più si fa orbo, e, come più guarda il sole, più s'accieca. Pel vizio, che non po' stare dov'è la virtù.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questa si trasmuta di femmina in maschio, e dimentica il primo sesso, e fura per invidia l'ova all'altre, ma i nati seguitano la vera madre.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questa co' la celidonia 'lumina i sua ciechi nati.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questa, trovando la tana del basilisco, coll'odore della sua sparsa orina, l'occide: l'odore della quale orina ancora, spesse volte, essa donnola occide.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questa ha due teste, l'una nel suo loco, l'altra nella coda, come se non bastassi, che da un solo loco gittassi il veneno.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questa sta sopra le piante, e si lancia come dardo, e passa attraverso le fiere, e l'uccide.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo ha similitudine colla cicogna, e, quando si sente ammalato, empie il gozzo d'acqua, e col becco si fa un cristero.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo, quando si sente morso dal ragno detto falange, mangia de' granchi, e si libera di tal veneno.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo medica i sua mali mangiando della edera.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questa, poi che le sono uscite le 'nteriora, ancora combatte coi cani e cacciatori.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo piglia sempre il colore della cosa, dove si posa, onde, insieme colle frondi dove si posano, spesso dalli elefanti son divorati.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Questo, quando ha ucciso il camaleone, si purga coll'alloro.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Amor, timor e reverenza: questo scrivi in tre sassi di gru.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il cardellino dà il tortomalio a' figlioli ingabbiati. — Prima morte che perdere libertà!", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il gallo non canta, se prima tre volte non batte l'ali; il papagallo, nel mutarsi pe' rami, non mette i piè, dove non ha prima messo il becco.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Per il ramo della noce, — che solo è percosso e battuto, quand'e' ha condotto a perfezione li sua frutti, — si dinota quelli, che, mediante il fine delle loro famose opere, son percossi dalla invidia per diversi modi.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La formica trovato uno grano di miglio, il grano sentendosi preso da quella gridò: «Se mi fai tanto piacere di lasciarmi fruire il mio desiderio del nascere, io ti renderò cento me medesimi.» E così fu fatto.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Lo specchio si groria forte tenendo dentro a sé specchiata la regina e, partita quella, lo specchio riman vile.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Acciocché la prosperità del corpo non guasti quella dell'ingegno, il pittore ovvero disegnatore dev'essere solitario.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Ciò che tu guadagni che non serve alla vita tua è in man d'altri senza tuo grado.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La più importante cosa che ne' discorsi della pittura trovar si possa, sono i movimenti appropriati agli accidenti mentali di ciascun animale, come desiderio, sprezzamento, ira, pietà e simili.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Quel pittore che non dubita poco acquista.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Il pittore è padrone di tutte le cose che possono cadere in pensiero all'uomo, perciocché s'egli ha desiderio di vedere bellezze che lo innamorino, egli è signore di generarle.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "La pittura è una poesia che si vede e non si sente, e la poesia è una pittura che si sente e non si vede. Adunque queste due poesie, o vuoi dire due pitture, hanno scambiati i sensi, per i quali esse dovrebbero penetrare all'intelletto.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Farai le figure in tale atto, il quale sia sufficiente a dimostrare quello che la figura ha nell'animo; altrimenti la tua arte non sarà laudabile.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "E veramente accade che sempre dove manca la ragione suppliscono le grida, la qual cosa non accade nelle cose certe.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "Sempre la pratica dev'essere edificata sopra la buona teorica.", Author = "Leonardo da Vinci" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Leonardo_da_Vinci", Text = "E se tu sarai solo, tu sarai tutto tuo.", Author = "Leonardo da Vinci" },
        };
    }
